import { IFrameReactContainer, useTranslation } from "@fanfanlo";
import { Box, Button, Stack, TextareaAutosize, Typography } from "@mui/material";
import { ScriptEditorContextLoader } from "@src/components/script-editor/data/context";
import { loadScrptEditorData } from "@src/components/script-editor/data/script-editor.data.intf";
import { marketHtmlUtils } from "@src/markets/market-html-utils";
import { useState, useCallback, useEffect, useRef } from "react";
import { scriptList, scriptMap, IScript } from "@src/components/script-editor/content/scripts";

export function ScriptEditorContent({ns}:{ns?:string}) {

    // 默认选择 SendNotification（索引2）
    const [selectedScript, setSelectedScript] = useState<IScript>(scriptList[2]);
    const [scriptContent, setScriptContent] = useState(scriptList[2].script);
    const [runScript, setRunScript] = useState('')
    const [contextData, setContextData] = useState(null);
    const { t } = useTranslation(`homepage/components/script-editor/content/content`)

    // 使用 useRef 标记是否正在加载，防止重复加载
    const isLoadingRef = useRef(false);

    // 使用 useEffect 异步加载数据，防止无限渲染
    useEffect(() => {
        // 防止重复加载
        if (isLoadingRef.current) {
            console.log(`[ScriptEditorContent] 数据已在加载中，跳过`);
            return;
        }

        console.log(`[ScriptEditorContent] 开始加载数据，ns=${ns}`);
        isLoadingRef.current = true;
        let isMounted = true;

        loadScrptEditorData(ns).then(result => {
            console.log(`[ScriptEditorContent] 数据加载完成`, result);
            if (isMounted) {
                setContextData(result);
                isLoadingRef.current = false;
            }
        }).catch(error => {
            console.error(`[ScriptEditorContent] 数据加载失败`, error);
            if (isMounted) {
                isLoadingRef.current = false;
            }
        });

        return () => {
            console.log(`[ScriptEditorContent] useEffect cleanup`);
            isMounted = false;
        };
    }, [ns]);

    // 创建稳定的加载函数引用，仅当 ns 改变时重新创建
    // 但不立即执行，而是让 ContextLoader 来执行
    const loadData = useCallback(() => {
        console.log(`[ScriptEditorContent] loadData 函数被调用`);
        // 直接返回已加载的数据或执行加载
        if (contextData) {
            return Promise.resolve(contextData);
        }
        return loadScrptEditorData(ns);
    }, [contextData, ns]);

    const handleScriptChange = (scriptName: string) => {
        console.log(`[ScriptEditorContent] 选择脚本:`, scriptName);
        const selected = scriptMap[scriptName];
        if (selected) {
        console.log(`[ScriptEditorContent] 选择脚本: 找到了`, scriptName);
            setSelectedScript(selected);
            setScriptContent(selected.script);
        }else{
            
        console.log(`[ScriptEditorContent] 选择脚本: 没找到`, scriptName);
        }
    }

    function onRunClick(){
        console.log(`[ScriptEditorContent] 执行脚本,脚本名称:${selectedScript.name}`);
        setRunScript('')
        setTimeout(()=>setRunScript(scriptContent), 100 * 3)
    }
    console.log('rendering ScriptEditorContent')
    return (
        <>
        <ScriptEditorContextLoader value={loadData}>
            <Box>
                <Typography variant="h5">{t(ns ? 'ScriptEditorContent.name.editScript' : 'ScriptEditorContent.name.createScript')}</Typography>
                <Stack direction={"column"} spacing={2}>
                    <Box>
                        {/* 脚本选择器 */}
                        <Stack direction={"row"} spacing={1} style={{marginBottom: '12px', alignItems: 'center'}}>
                            <Typography variant="body2" style={{fontWeight: 500}}>选择脚本:</Typography>
                            <select
                                value={selectedScript.name}
                                onChange={(e) => handleScriptChange(e.target.value)}
                                style={{padding: '8px 12px', borderRadius: '4px', border: '1px solid #ccc'}}
                            >
                                {scriptList.map((script) => (
                                    <option key={script.name} value={script.name}>
                                        {script.name} - {script.description}
                                    </option>
                                ))}
                            </select>
                        </Stack>
                    </Box>
                    <Box>
                        <Button>examples2</Button>
                        <Button>docs</Button>
                        <Button onClick={onRunClick}>run</Button>
                    </Box>
                    <Box>
                        <TextareaAutosize
                        value={scriptContent}
                        onChange={(e)=>setScriptContent(e.target.value)}
                         style={{width:"100%",minHeight:"200px"}} />
                    </Box>
                    <Box></Box>
                    <Box>
                        {runScript && <IFrameReactContainer
                        content={runScript}
                        urlAsContent={true}
                        htmlBuilder={marketHtmlUtils.mergeHtml}
                        />}
                    </Box>
                </Stack>
            </Box>
        </ScriptEditorContextLoader>
        </>
    )
}
